#include <stdint.h>
#include <stddef.h>
uint8_t crc8(const uint8_t *data, size_t len) { uint8_t crc = 0; for(size_t i=0;i<len;i++){ crc ^= data[i]; for(int b=0;b<8;b++) crc = (uint8_t)((crc & 0x80) ? (crc << 1) ^ 0x07 : crc << 1); } return crc; }
